package com.baz.divisas.general.util;

import static org.assertj.core.api.Assertions.assertThat;

import java.security.PublicKey;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.junit.jupiter.MockitoExtension;
import org.mockito.junit.jupiter.MockitoSettings;
import org.mockito.quality.Strictness;

@ExtendWith(MockitoExtension.class)
@MockitoSettings(strictness = Strictness.LENIENT)
public class RSAUtilsPagosDigitalesTest {

	@Test
	public void testGetPublicKey() {
		PublicKey pub = RSAUtilsPagosDigitales.getPublicKey("");
		assertThat(pub).isNotNull();
	}
	
	@Test
	public void testEncryptOAE256() {
		String encripta = RSAUtilsPagosDigitales.EncryptOAE256("20017604325424869569", "");
		assertThat(encripta).isNotNull();
	}
	
	@Test
	public void testDecryptOAE256() {
		String descencripta = RSAUtilsPagosDigitales.DecryptOAE256("","");
		assertThat(descencripta).isNotNull();
	}

}
